input.newString:
import { revalidatePath } from 'next/cache';

let notificationPreference = false;

async function toggleNotificationPreference() {
  'use server';
  notificationPreference = !notificationPreference;
  revalidatePath('/');
}

export default function Home() {
  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotificationPreference}>
        <label>
          <input 
            type="checkbox" 
            checked={notificationPreference} 
            onChange={() => {}} 
          />
          Enable Notifications
        </label>
        <button type="submit">Save</button>
      </form>
      <p>Current preference: {notificationPreference ? 'ON' : 'OFF'}</p>
    </main>
  );
}

